produceCaseWithBattery.vre:effects:
const battery = <battery>;
const caseWithSensorModule = <casewithsensormodule>;
const caseWithBattery = <casewithbattery>;
caseWithBattery.xpos' = battery.xpos == xpos && battery.ypos == ypos
  && caseWithSensorModule.xpos == xpos && caseWithSensorModule.ypos == ypos ? xpos : caseWithBattery.xpos;
caseWithBattery.ypos' = battery.xpos == xpos && battery.ypos == ypos
  && caseWithSensorModule.xpos == xpos && caseWithSensorModule.ypos == ypos ? ypos : caseWithBattery.ypos;
caseWithBattery.state' = battery.xpos == xpos && battery.ypos == ypos
  && caseWithSensorModule.xpos == xpos && caseWithSensorModule.ypos == ypos ? "initialState" : caseWithBattery.state;
output.success = battery.xpos == xpos && battery.ypos == ypos
  && caseWithSensorModule.xpos == xpos && caseWithSensorModule.ypos == ypos;

